#include QMK_KEYBOARD_H
#include "modules/drag_scroll/drag_scroll.h"

enum custom_keycodes {
    DRAG_SCROLL = QK_KB_0,
    ALT_CLK,
    GUI_CLK,
    SHIFT_CLK,
    CTRL_CLK,
};

static void send_modified_click(uint8_t modifier) {
    register_code(modifier);
    tap_code(KC_BTN1);
    unregister_code(modifier);
}

bool process_record_user(uint16_t keycode, keyrecord_t *record) {

    switch (keycode) {

        case DRAG_SCROLL:
            drag_scroll_set(record->event.pressed);
            return false;

        case ALT_CLK:
            if (record->event.pressed) {
                send_modified_click(KC_LALT);
            }
            return false;

        case GUI_CLK:
            if (record->event.pressed) {
                send_modified_click(KC_LGUI);
            }
            return false;

        case SHIFT_CLK:
            if (record->event.pressed) {
                send_modified_click(KC_LSFT);
            }
            return false;

        case CTRL_CLK:
            if (record->event.pressed) {
                send_modified_click(KC_LCTL);
            }
            return false;
    }

    return true;
}

void keyboard_post_init_user(void) {
    drag_scroll_init();
}

void housekeeping_task_user(void) {
    drag_scroll_task();
}
